private theorem rpow_mul_exp_neg_le_factorial {y c a : ℝ} (n : ℕ)
    (hy : 0 ≤ y) (hc : 0 < c) (ha : 0 ≤ a) (han : a ≤ n) :
    y ^ a * Real.exp (-c * y) ≤ 1 + n.factorial / c ^ n

